import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getUnreadCount } from '../services/api';

export default function Navbar() {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [unread, setUnread] = useState(0);

  useEffect(() => {
    if (user?.email) {
      getUnreadCount(user.email)
        .then(r => setUnread(r.data.count))
        .catch(() => {});
    }
  }, [user, location.pathname]);

  const logout = () => { signOut(); navigate('/login'); };
  const isActive = (path) => location.pathname === path ? 'nav-link active' : 'nav-link';

  if (!user) return null;

  return (
    <nav className="navbar">
      <Link to="/dashboard" className="brand">⚡ InternHub</Link>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
        {user.role === 'STUDENT' && (
          <>
            <Link to="/dashboard" className={isActive('/dashboard')}>Explore</Link>
            <Link to="/my-applications" className={isActive('/my-applications')}>Applications</Link>
            <Link to="/saved" className={isActive('/saved')}>Saved</Link>
            <Link to="/profile" className={isActive('/profile')}>Profile</Link>
            <Link to="/notifications" className={isActive('/notifications')} style={{ position: 'relative', display:'flex', alignItems:'center' }}>
              🔔
              {unread > 0 && <span className="notif-badge">{unread}</span>}
            </Link>
          </>
        )}
        {user.role === 'ADMIN' && (
          <>
            <Link to="/admin" className={isActive('/admin')}>Dashboard</Link>
            <Link to="/admin/internships" className={isActive('/admin/internships')}>Internships</Link>
            <Link to="/admin/applications" className={isActive('/admin/applications')}>Applications</Link>
            <Link to="/admin/users" className={isActive('/admin/users')}>Users</Link>
          </>
        )}
        <span style={{ color: 'var(--text2)', fontSize: '0.82rem', margin: '0 8px' }}>
          Hi, {user.name?.split(' ')[0]}
        </span>
        <button className="nav-btn" onClick={logout}>Logout</button>
      </div>
    </nav>
  );
}
